            codepoint = (codepoint << 4U) | digit;
        }
        if (codepoint >= 0xd800U && codepoint <= 0xdbffU) {
            if (end - cursor < 6U || doc->source[cursor] != '\\' || doc->source[cursor + 1U] != 'u') return false;
            cursor += 2U;
